-- Sign-in sessions owned by the Go API (tea-pos v2). The cookie holds a random
-- token; only its SHA-256 is stored, so a leaked table cannot sign anyone in.
CREATE TABLE public.sessions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    token_hash bytea NOT NULL UNIQUE,
    user_id uuid NOT NULL REFERENCES public.users (id) ON DELETE CASCADE,
    app text NOT NULL CHECK (app IN ('seller', 'backoffice')),
    created_at timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    ip text,
    user_agent text
);

CREATE INDEX sessions_user_id_idx ON public.sessions (user_id);

-- Only Go's connection (which skips row-level security) reads it; with no policy,
-- the old app's clients cannot.
ALTER TABLE public.sessions ENABLE ROW LEVEL SECURITY;
